+        rbdOpts += ":client_mount_timeout=30";
+
+        return rbdOpts;
+    }
+
+    private PhysicalDiskFormat format;
+    private long size;
+    private long virtualSize;
+
+    public KVMPhysicalDisk(String path, String name, KVMStoragePool pool) {
+        this.path = path;
+        this.name = name;
+        this.pool = pool;
+    }
