+
+public class KVMPhysicalDiskTest extends TestCase {
+
+    public void testRBDStringBuilder() {
+        assertEquals(KVMPhysicalDisk.RBDStringBuilder("ceph-monitor", 8000, "admin", "supersecret", "volume1"),
