+        disk.setSize(1024);
+        disk.setVirtualSize(2048);
+        assertEquals(disk.getSize(), 1024);
+        assertEquals(disk.getVirtualSize(), 2048);
+
+        disk.setFormat(PhysicalDiskFormat.RAW);
+        assertEquals(disk.getFormat(), PhysicalDiskFormat.RAW);
+    }
